{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Validate required keys (assuming they exist)
    if not nodes or not core_distance or not distances:
        raise ValueError("Missing required fields")

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        core_u = core_distance[u]
        core_v = core_distance[v]
        w = max(core_u, core_v, d)
        # Canonicalize endpoints: ensure u < v lexicographically
        if u > v:
            u, v = v, u
        edges.append((w, u, v))

    # Sort by weight, then by source, then by target
    edges.sort()

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    edges_added = 0
    n = len(nodes)
    required_edges = n - 1

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            edges_added += 1
            if edges_added == required_edges:
                break

    if edges_added != required_edges:
        raise ValueError("Graph is disconnected; MST cannot be formed")

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
